-- Idempotent data migration for catalogs exposed by the public API.
-- Keep catalog data in SQL, not in Rust constants or startup seed functions.

ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, currencies = EXCLUDED.currencies, status = EXCLUDED.status, updated_at = now();

ON CONFLICT (name) DO UPDATE SET role = EXCLUDED.role, country = EXCLUDED.country, currency = EXCLUDED.currency, domain = EXCLUDED.domain, icon_url = EXCLUDED.icon_url, schemes = EXCLUDED.schemes, updated_at = now();

